import React, { useEffect, useMemo, useState } from 'react';
import { t } from '../../i18n';
import { getLanguageCssVars } from '../ColorsMap';
import { getDialogData, getDialogRoles, listDialogsForLanguage, listFormsForDialog } from './Dialogs';
import './DialogsMenu.css';

const FORM_OPTIONS = ['formal', 'informal'];

const DialogsMenu = ({ onBack, uiLang, learningLang, onStart }) => {
  const activeLanguage = (learningLang || 'ES').toUpperCase();
  const dialogOptions = useMemo(
    () => listDialogsForLanguage(activeLanguage),
    [activeLanguage]
  );
  const [selectedDialog, setSelectedDialog] = useState('');
  const [selectedDifficulty, setSelectedDifficulty] = useState('easy');
  const [selectedRole, setSelectedRole] = useState('');
  const [selectedForm, setSelectedForm] = useState('formal');

  useEffect(() => {
    setSelectedDialog('');
    setSelectedRole('');
  }, [activeLanguage]);

  const availableForms = useMemo(() => {
    if (!selectedDialog) return [];
    return listFormsForDialog(activeLanguage, selectedDialog);
  }, [activeLanguage, selectedDialog]);

  useEffect(() => {
    if (!selectedDialog) return;
    if (availableForms.length === 0) return;
    if (!availableForms.includes(selectedForm)) {
      setSelectedForm(availableForms[0]);
    }
  }, [availableForms, selectedDialog, selectedForm]);

  useEffect(() => {
    setSelectedRole('');
  }, [selectedDialog, selectedForm]);

  const dialogData = useMemo(() => {
    if (!selectedDialog) return null;
    return getDialogData(activeLanguage, selectedDialog, selectedForm);
  }, [activeLanguage, selectedDialog, selectedForm]);

  const roles = useMemo(() => getDialogRoles(dialogData), [dialogData]);

  const themeVars = getLanguageCssVars(activeLanguage);

  return (
    <div className="dialogs-menu-container" style={themeVars}>
      <button className="dialogs-menu-back-button" onClick={onBack}>{t('back', uiLang)}</button>
      <h1 className="dialogs-menu-title">{t('dialogsTitle', uiLang)}</h1>

      <div className="dialogs-menu-filters">
        <div className="dialogs-menu-field">
          <label className="dialogs-menu-label" htmlFor="dialogs-menu-dialog">
            {t('dialogsSelectDialog', uiLang)}
          </label>
          <select
            id="dialogs-menu-dialog"
            className="dialogs-menu-select"
            value={selectedDialog}
            onChange={(event) => setSelectedDialog(event.target.value)}
          >
            <option value="">
              {t('dialogsSelectPlaceholder', uiLang)}
            </option>
            {dialogOptions.length === 0 && (
              <option value="" disabled>
                {t('dialogsNoDialogs', uiLang)}
              </option>
            )}
            {dialogOptions.map(option => (
              <option key={option} value={option}>{option}</option>
            ))}
          </select>
        </div>

        <div className="dialogs-menu-field">
          <label className="dialogs-menu-label" htmlFor="dialogs-menu-difficulty">
            {t('dialogsSelectDifficulty', uiLang)}
          </label>
          <select
            id="dialogs-menu-difficulty"
            className="dialogs-menu-select"
            value={selectedDifficulty}
            onChange={(event) => setSelectedDifficulty(event.target.value)}
          >
            <option value="easy">{t('dialogsDifficultyEasy', uiLang)}</option>
            <option value="medium">{t('dialogsDifficultyMedium', uiLang)}</option>
            <option value="hard">{t('dialogsDifficultyHard', uiLang)}</option>
          </select>
        </div>

        <div className="dialogs-menu-field">
          <label className="dialogs-menu-label" htmlFor="dialogs-menu-form">
            {t('dialogsSelectForm', uiLang)}
          </label>
          <select
            id="dialogs-menu-form"
            className="dialogs-menu-select"
            value={selectedForm}
            onChange={(event) => setSelectedForm(event.target.value)}
          >
            {FORM_OPTIONS.map(formKey => (
              <option
                key={formKey}
                value={formKey}
                disabled={selectedDialog && availableForms.length > 0 && !availableForms.includes(formKey)}
              >
                {formKey === 'formal'
                  ? t('dialogsFormFormal', uiLang)
                  : t('dialogsFormInformal', uiLang)}
              </option>
            ))}
          </select>
        </div>

        {selectedDialog && (
          <div className="dialogs-menu-field">
            <label className="dialogs-menu-label" htmlFor="dialogs-menu-role">
              {t('dialogsSelectRole', uiLang)}
            </label>
            <select
              id="dialogs-menu-role"
              className="dialogs-menu-select"
              value={selectedRole}
              onChange={(event) => setSelectedRole(event.target.value)}
              disabled={roles.length === 0}
            >
              <option value="">
                {t('dialogsSelectPlaceholder', uiLang)}
              </option>
              {roles.map(role => (
                <option key={role} value={role}>{role}</option>
              ))}
            </select>
          </div>
        )}
      </div>

      <button
        className="dialogs-menu-start-button"
        onClick={() => {
          if (!selectedDialog || !onStart) return;
          onStart({
            languageId: activeLanguage,
            dialogName: selectedDialog,
            form: selectedForm,
            difficulty: selectedDifficulty,
            role: selectedRole
          });
        }}
        disabled={!selectedDialog}
      >
        {t('dialogsStart', uiLang)}
      </button>
    </div>
  );
};

export default DialogsMenu;
