import React, { Component } from 'react'
import { t } from '../../i18n'
import { loadAvailableLanguageIds } from '../../utils/availableLanguages'
import { getLanguageColors, getLanguageCssVars } from '../ColorsMap'
import './MainMenu.css'

const LANGUAGES = [
  { id: 'FR', name: 'Français' },
  { id: 'EN', name: 'English' },
  { id: 'ES', name: 'Español' },
  { id: 'DE', name: 'Deutsch' },
  { id: 'RU', name: 'Русский' },
  { id: 'JA', name: '日本語' },
  { id: 'ZH', name: '中文' },
  { id: 'IT', name: 'Italiano' },
  { id: 'PT', name: 'Português' },
  { id: 'KO', name: '한국어' }
];

export class MainMenu extends Component {
  state = {
    isLangMenuOpen: false,
    availableLanguageIds: new Set()
  };

  dragStartX = null;

  async componentDidMount() {
    const ids = await loadAvailableLanguageIds(LANGUAGES.map(lang => lang.id));
    this.setState({ availableLanguageIds: new Set(ids) });
  }

  getLanguageColor = (languageId) => {
    return getLanguageColors(languageId).accent;
  };

  getLanguageName = (languageId) => {
    const nameMap = {
      'FR': 'Français',
      'EN': 'English',
      'ES': 'Español',
      'DE': 'Deutsch',
      'RU': 'Русский',
      'JA': '日本語',
      'ZH': '中文',
      'IT': 'Italiano',
      'PT': 'Português',
      'KO': '한국어'
    };
    return nameMap[languageId] || 'Unknown';
  };

  getLanguageImage = (languageId) => {
    const imageMap = {
      'EN': 'engBird',
      'ES': 'espBird',
      'FR': 'frBird',
      'DE': 'deBird',
      'RU': 'ruBird',
      'JA': 'jaBird',
      'ZH': 'zhBird',
      'IT': 'itBird',
      'PT': 'ptBird',
      'KO': 'koBird'
    };
    const imageName = imageMap[languageId] || 'engBird';
    return `./img/${imageName}.png`;
  };

  setNextLearningLanguage = (learningList, direction) => {
    if (!Array.isArray(learningList) || learningList.length < 2) return;
    const { onSetActiveLearning } = this.props;
    if (!onSetActiveLearning) return;

    const currentIndex = 0;
    const nextIndex = direction === 'left'
      ? (currentIndex + 1) % learningList.length
      : (currentIndex - 1 + learningList.length) % learningList.length;
    const nextLanguageId = learningList[nextIndex];
    onSetActiveLearning(nextLanguageId);
  };

  handleGalleryDragStart = (clientX) => {
    this.dragStartX = clientX;
  };

  handleGalleryDragEnd = (clientX, learningList) => {
    if (this.dragStartX === null) return;
    const deltaX = clientX - this.dragStartX;
    const threshold = 50;

    if (Math.abs(deltaX) > threshold) {
      if (deltaX < 0) {
        this.setNextLearningLanguage(learningList, 'left');
      } else {
        this.setNextLearningLanguage(learningList, 'right');
      }
    }

    this.dragStartX = null;
  };

  render() {
    const { languages, setCardsMenuMode, onDeleteAccount, onAddLearningLanguage, onSetActiveLearning } = this.props;
    const uiLang = languages?.native;
    const learningList = Array.isArray(languages?.learning)
      ? languages.learning
      : (languages?.learning ? [languages.learning] : []);
    const primaryLearning = learningList[0] || null;
    const learningSet = new Set(learningList);
    const learningItems = learningList
      .map(id => LANGUAGES.find(lang => lang.id === id))
      .filter(Boolean);
    const inactiveItems = LANGUAGES.filter(lang => !learningSet.has(lang.id) && lang.id !== uiLang);
    const availableLanguageIds = this.state.availableLanguageIds;
    const learningLanguageColor = primaryLearning ? this.getLanguageColor(primaryLearning) : null;
    const learningLanguageName = primaryLearning ? this.getLanguageName(primaryLearning) : null;
    const learningLanguageImage = primaryLearning ? this.getLanguageImage(primaryLearning) : null;
    const learningNames = learningList.map(id => this.getLanguageName(id)).join(', ');
    const activeThemeVars = getLanguageCssVars(primaryLearning);

    const galleryItems = (() => {
      if (!primaryLearning) return [];
      if (learningList.length === 1) {
        return [{ id: primaryLearning, position: 'center' }];
      }
      if (learningList.length === 2) {
        return [
          { id: learningList[1], position: 'left' },
          { id: primaryLearning, position: 'center' }
        ];
      }
      return [
        { id: learningList[learningList.length - 1], position: 'left' },
        { id: primaryLearning, position: 'center' },
        { id: learningList[1], position: 'right' }
      ];
    })();

    return (
      <div className="main-menu-container" style={activeThemeVars}>
        <div className="main-menu-header">
          {learningLanguageColor && (
            <div
              className="learning-language-box"
              onClick={() => this.setState(prev => ({ isLangMenuOpen: !prev.isLangMenuOpen }))}
            >
              <div className="language-color-circle" style={{ backgroundColor: learningLanguageColor }}></div>
              <span className="language-name">{learningLanguageName}</span>
              <span className="language-caret">▼</span>
            </div>
          )}
          {this.state.isLangMenuOpen && (
            <div className="learning-language-dropdown">
              <div className="learning-language-list">
                {learningItems.map(lang => (
                  <div
                    key={lang.id}
                    className="learning-language-item"
                    onClick={() => {
                      if (!onSetActiveLearning) return;
                      onSetActiveLearning(lang.id);
                    }}
                  >
                    <span
                      className="language-color-dot"
                      style={{ backgroundColor: this.getLanguageColor(lang.id) }}
                    ></span>
                    <span className="language-option-name">{lang.name}</span>
                  </div>
                ))}
                <div className="learning-language-separator" />
                {inactiveItems.map(lang => (
                  <div
                    key={lang.id}
                    className={`learning-language-item learning-language-item--inactive ${
                      availableLanguageIds.has(lang.id) ? '' : 'learning-language-item--locked'
                    }`}
                    onClick={() => {
                      if (!availableLanguageIds.has(lang.id)) return;
                      if (!onAddLearningLanguage) return;
                      onAddLearningLanguage(lang.id);
                    }}
                  >
                    <span className="language-color-dot language-color-dot--inactive"></span>
                    <span className="language-option-name">{lang.name}</span>
                    {!availableLanguageIds.has(lang.id) && (
                      <span className="language-option-lock">🔒</span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="main-menu-content">
          {learningLanguageImage && (
            <div
              className="learning-language-gallery"
              onMouseDown={(e) => this.handleGalleryDragStart(e.clientX)}
              onMouseUp={(e) => this.handleGalleryDragEnd(e.clientX, learningList)}
              onMouseLeave={() => { this.dragStartX = null; }}
              onTouchStart={(e) => this.handleGalleryDragStart(e.touches[0].clientX)}
              onTouchEnd={(e) => this.handleGalleryDragEnd(e.changedTouches[0].clientX, learningList)}
              onCopy={(e) => e.preventDefault()}
              onContextMenu={(e) => e.preventDefault()}
            >
              {galleryItems.map(item => (
                <div
                  key={`${item.position}-${item.id}`}
                  className={`learning-language-gallery-item learning-language-gallery-item--${item.position}`}
                  onClick={() => {
                    if (item.position !== 'center' && onSetActiveLearning) {
                      onSetActiveLearning(item.id);
                    }
                  }}
                >
                  <img
                    src={this.getLanguageImage(item.id)}
                    alt={`${t('learningLabel', uiLang)} ${this.getLanguageName(item.id)}`}
                    className="learning-language-image"
                    draggable={false}
                    onDragStart={(e) => e.preventDefault()}
                    onContextMenu={(e) => e.preventDefault()}
                  />
                </div>
              ))}
            </div>
          )}

          <div className="main-menu-items">
            <div className="menu-item" onClick={() => setCardsMenuMode(true)}>{t('menuCards', uiLang)}</div>
            <div className="menu-item" onClick={() => this.props.setDialogsMenuMode(true)}>{t('menuDialogs', uiLang)}</div>
            <div className="menu-item">{t('menuStats', uiLang)}</div>
            <div
              className="menu-item"
              onClick={() => {
                if (!onDeleteAccount) return;
                if (window.confirm(t('deleteAccountConfirm', uiLang))) {
                  onDeleteAccount();
                }
              }}
            >
              {t('menuDeleteAccount', uiLang)}
            </div>
            <div className="menu-item" onClick={this.props.onLogout}>{t('menuLogout', uiLang)}</div>
          </div>
        </div>

        <div className="main-menu-languages-display">
          <strong>{t('selectedLanguages', uiLang)}</strong>
          {t('nativeLabel', uiLang)} {languages?.native || t('notSelected', uiLang)}<br/>
          {t('learningLabel', uiLang)} {learningNames || t('notSelected', uiLang)}
        </div>
      </div>
    )
  }
}

export default MainMenu