export const getLanguageColors = (languageId) => {
	if (!languageId) return DEFAULT_COLORS;
	return LANGUAGE_COLORS[languageId] || DEFAULT_COLORS;
};

export const getLanguageCssVars = (languageId) => {
	const colors = getLanguageColors(languageId);
	return {
		'--bg-start': colors.bgStart,
		'--bg-end': colors.bgEnd,
		'--surface': colors.surface,
		'--surface-strong': colors.surfaceStrong,
		'--text': colors.text,
		'--text-muted': colors.textMuted,
		'--accent': colors.accent,
		'--accent-soft': colors.accentSoft,
		'--accent-strong': colors.accentStrong,
		'--border': colors.border,
		'--shadow-color': colors.shadowColor,
		'--card-front-start': colors.cardFrontStart,
		'--card-front-end': colors.cardFrontEnd,
		'--card-back-start': colors.cardBackStart,
		'--card-back-end': colors.cardBackEnd,
		'--chip-front-bg': colors.chipFrontBg,
		'--chip-back-bg': colors.chipBackBg,
		'--danger': colors.danger,
		'--danger-bg': colors.dangerBg,
		'--success': colors.success,
		'--success-bg': colors.successBg
	};
};
