/**
 * userService.js — вся логика работы с пользователем напрямую через Supabase.
 * Заменяет Express-backend (server.js) без изменения поведения приложения.
 */

import { supabase } from './supabase';
import { loadLanguageTable } from '../utils/availableLanguages';

// ─── Helpers ──────────────────────────────────────────────────────────────────

const normalizeLanguageId = (id) => String(id || '').trim().toUpperCase();
const isValidLanguageId = (id) => /^[A-Z]{2,5}$/.test(id || '');
const isValidUsername = (name) => /^[A-Za-z0-9_-]+$/.test(name || '');
const getTableName = (languageId) => `UserTable_${languageId}`;

const idFieldByLang = { EN: 'EN_id', DE: 'DE_id', ES: 'ES_id', RU: 'RU_id' };
const getIdField = (languageId) => idFieldByLang[languageId] || `${languageId}_id`;

const normalizeSection = (value) => {
  const n = Number(value);
  return Number.isNaN(n) ? 1 : Math.max(1, Math.min(5, Math.trunc(n)));
};

/** Возвращает email-идентификатор для Supabase Auth из имени пользователя. */
const toAuthEmail = (username) => `${username.toLowerCase().trim()}@languageup.internal`;

// ─── Auth ─────────────────────────────────────────────────────────────────────

/**
 * Логин. Возвращает отображаемое имя пользователя.
 * @throws {Error} при неверных данных
 */
export const login = async (username, password) => {
  if (!isValidUsername(username) || !password) {
    throw new Error('invalid_input');
  }
  const email = toAuthEmail(username);
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) throw error;
  return data.user?.user_metadata?.username || username;
};

/**
 * Регистрация. Возвращает отображаемое имя пользователя.
 * Требует отключённого email-подтверждения в Supabase (Authentication → Settings).
 * @throws {Error} при конфликте или невалидных данных
 */
export const register = async (username, password) => {
  const trimmed = username.trim();
  if (!isValidUsername(trimmed) || !password) {
    throw new Error('invalid_input');
  }
  const email = toAuthEmail(trimmed);

  const { data, error } = await supabase.auth.signUp({
    email,
    password,
    options: { data: { username: trimmed } }
  });

  if (error) {
    console.error('[register] signUp error:', error.message, error);
    throw error;
  }
  if (!data.user) throw new Error('registration_failed');
  if (!data.session) {
    console.warn('[register] signUp returned no session — email confirmation may be ON in Supabase Dashboard');
    throw new Error('email_confirmation_required');
  }

  // Хэшируем пароль через Web Crypto API (SHA-256 + случайная соль)
  // Формат: sha256:<16-байт соль hex>:<хэш hex>
  // Эта запись только для видимости в Supabase Table Editor — не влияет на функционал
  try {
    const salt = window.crypto.getRandomValues(new Uint8Array(16));
    const saltHex = Array.from(salt).map((b) => b.toString(16).padStart(2, '0')).join('');
    const encoded = new TextEncoder().encode(saltHex + password);
    const hashBuf = await window.crypto.subtle.digest('SHA-256', encoded);
    const hashHex = Array.from(new Uint8Array(hashBuf)).map((b) => b.toString(16).padStart(2, '0')).join('');
    const passwordHash = `sha256:${saltHex}:${hashHex}`;
    const { error: usersErr } = await supabase
      .from('users')
      .insert({ user_id: data.user.id, username: trimmed, password_hash: passwordHash });
    if (usersErr && usersErr.code !== '23505') {
      console.warn('[register] public.users insert skipped:', usersErr.message);
    }
  } catch (e) {
    console.warn('[register] public.users insert failed (non-fatal):', e.message);
  }

  // Создаём строку настроек при первой регистрации
  const { error: settingsErr } = await supabase
    .from('user_settings')
    .insert({ user_id: data.user.id, native: null, learning: [] });

  // Игнорируем «уже существует» (дубль вставки)
  if (settingsErr && settingsErr.code !== '23505') {
    console.error('[register] user_settings insert error:', settingsErr.message, settingsErr);
    throw settingsErr;
  }

  return data.user.user_metadata?.username || trimmed;
};

/** Выход из системы. */
export const logout = async () => {
  await supabase.auth.signOut();
};

/**
 * Удаление аккаунта через хранимую функцию delete_current_user().
 * Данные в user_settings и user_language_tables удаляются каскадно.
 */
export const deleteAccount = async () => {
  const { error } = await supabase.rpc('delete_current_user');
  if (error) throw error;
};

/** Возвращает текущую Supabase-сессию или null. */
export const getSession = async () => {
  const { data: { session } } = await supabase.auth.getSession();
  return session;
};

/** Возвращает отображаемое имя текущего пользователя или null. */
export const getCurrentUsername = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  return user?.user_metadata?.username || null;
};

// ─── Settings ─────────────────────────────────────────────────────────────────

/** Загружает настройки текущего пользователя. */
export const getUserSettings = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const { data, error } = await supabase
    .from('user_settings')
    .select('native, learning')
    .eq('user_id', user.id)
    .maybeSingle();

  if (error) throw error;

  if (!data) {
    await supabase.from('user_settings').insert({ user_id: user.id, native: null, learning: [] });
    return { native: null, learning: [] };
  }

  return {
    native: data.native || null,
    learning: Array.isArray(data.learning) ? data.learning : []
  };
};

/** Сохраняет настройки текущего пользователя. */
export const saveUserSettings = async (settings) => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  const native = settings?.native ? normalizeLanguageId(settings.native) : null;
  const learningRaw = Array.isArray(settings?.learning) ? settings.learning : [];
  const learning = [...new Set(learningRaw.map(normalizeLanguageId).filter(isValidLanguageId))];

  const { error } = await supabase
    .from('user_settings')
    .upsert(
      { user_id: user.id, native, learning, updated_at: new Date().toISOString() },
      { onConflict: 'user_id' }
    );

  if (error) throw error;

  // Убеждаемся, что строки для изучаемых языков существуют
  for (const languageId of learning) {
    await ensureLanguageTableRow(user.id, languageId);
  }
};

// ─── User language table ───────────────────────────────────────────────────────

/** Создаёт строку таблицы прогресса по языку, если её ещё нет. */
const ensureLanguageTableRow = async (userId, languageId) => {
  const tableName = getTableName(languageId);

  const { data: existing } = await supabase
    .from('user_language_tables')
    .select('user_id')
    .eq('user_id', userId)
    .eq('table_name', tableName)
    .maybeSingle();

  if (existing) return;

  const defaultData = await buildDefaultTableData(languageId);

  const { error } = await supabase.from('user_language_tables').insert({
    user_id: userId,
    language_id: languageId,
    table_name: tableName,
    table_data: defaultData
  });

  // Игнорируем race-condition дубль
  if (error && error.code !== '23505') throw error;
};

/** Строит начальную таблицу прогресса из словарного JSON.
 * Формат хранения: { ES_id: x, section: 1 } */
const buildDefaultTableData = async (languageId) => {
  const idField = getIdField(languageId);
  const wordTable = await loadLanguageTable(languageId);

  return wordTable
    .map((item) => {
      const wordId = Number(item?.[idField]);
      if (Number.isNaN(wordId) || wordId <= 0) return null;
      return { [idField]: wordId, section: 1 };
    })
    .filter(Boolean);
};

/**
 * Возвращает таблицу прогресса пользователя по языку.
 * Формат: [{wordId: number, section: number}, ...]
 */
export const getUserTable = async (languageId) => {
  const langId = normalizeLanguageId(languageId);
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');

  await ensureLanguageTableRow(user.id, langId);

  const tableName = getTableName(langId);
  const idField = getIdField(langId);

  const { data, error } = await supabase
    .from('user_language_tables')
    .select('table_data')
    .eq('user_id', user.id)
    .eq('table_name', tableName)
    .single();

  if (error) throw error;

  const list = Array.isArray(data?.table_data) ? data.table_data : [];

  // Поддержка обоих форматов: старый {ES_id: x} и новый {wordId: x}
  return list
    .map((item) => {
      const wordId = Number(item?.wordId ?? item?.[idField]);
      if (Number.isNaN(wordId) || wordId <= 0) return null;
      return { wordId, section: normalizeSection(item?.section ?? item?.Section) };
    })
    .filter(Boolean)
    .sort((a, b) => a.wordId - b.wordId);
};

/**
 * Сохраняет таблицу прогресса пользователя по языку.
 * @param {string} languageId
 * @param {Array<{wordId: number, section: number}>} tableData
 */
export const saveUserTable = async (languageId, tableData) => {
  const langId = normalizeLanguageId(languageId);
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('not_authenticated');
  if (!Array.isArray(tableData)) throw new Error('invalid_data');

  await ensureLanguageTableRow(user.id, langId);

  const tableName = getTableName(langId);
  const idField = getIdField(langId);
  const normalized = tableData
    .map((item) => {
      const wordId = Number(item?.wordId);
      if (Number.isNaN(wordId) || wordId <= 0) return null;
      return { [idField]: wordId, section: normalizeSection(item?.section) };
    })
    .filter(Boolean)
    .sort((a, b) => a[idField] - b[idField]);

  const { error } = await supabase
    .from('user_language_tables')
    .update({ table_data: normalized, updated_at: new Date().toISOString() })
    .eq('user_id', user.id)
    .eq('table_name', tableName);

  if (error) throw error;
};
