const getLang = (nativeId) => {
  const normalized = nativeId || DEFAULT_LANG;
  return translations[normalized] ? normalized : DEFAULT_LANG;
};

const interpolate = (template, params) => {
  if (!params) return template;
  return Object.keys(params).reduce((result, key) => {
    return result.replace(new RegExp(`\\{${key}\\}`, 'g'), String(params[key]));
  }, template);
};

const t = (key, nativeId, params) => {
  const lang = getLang(nativeId);
  const value = translations[lang]?.[key] || translations[DEFAULT_LANG]?.[key] || key;
  return interpolate(value, params);
};

const wordCountLabel = (count, nativeId) => {
  const lang = getLang(nativeId);
  if (lang === 'RU') {
    const mod10 = count % 10;
    const mod100 = count % 100;
    if (mod10 === 1 && mod100 !== 11) return 'слово';
    if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 'слова';
    return 'слов';
  }
  if (lang === 'JA') return '単語';
  if (lang === 'ZH') return '单词';
  if (lang === 'KO') return '단어';
  if (lang === 'ES') return count === 1 ? 'palabra' : 'palabras';
  if (lang === 'DE') return count === 1 ? 'Wort' : 'Worte';
  if (lang === 'FR') return count === 1 ? 'mot' : 'mots';
  if (lang === 'IT') return count === 1 ? 'parola' : 'parole';
  if (lang === 'PT') return count === 1 ? 'palavra' : 'palavras';
  return count === 1 ? 'word' : 'words';
};

export { t, wordCountLabel };
